//! `gen/rules-index`: the index of every ADR rule, and the baseline of the ADRs that a project marks as security areas.

use std::fmt::Write as _;
use std::sync::LazyLock;

use anyhow::Result;
use regex::Regex;

use super::Output;
use tabkit_core::config::Config;
use tabkit_core::repo::Repo;

const ID: &str = "gen/rules-index";
const GENERATED: &str =
    "<!-- Generated by tabkit. Edit the Rules section of the ADR, then run `tabkit gen`. -->";

static ADR_FILE: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"^(\d{4})-[a-z0-9-]+\.md$").expect("a built-in pattern compiles"));
static TITLE: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"^# ADR-(\d{4}): (.+)$").expect("a built-in pattern compiles"));
static ANNOTATION: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(r"`\((CI|enforced|ref): ([^)]*)\)`").expect("a built-in pattern compiles")
});
static ADR_LINK: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(r"\]\(((?:\d{4}-[a-z0-9-]+|README|_template)\.md)\)")
        .expect("a built-in pattern compiles")
});
static UP_LINK: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"\]\(\.\./([^)]+)\)").expect("a built-in pattern compiles"));

struct Adr {
    num: String,
    title: String,
    file: String,
    rules: Vec<Rule>,
}

struct Rule {
    text: String,
    gates: Vec<(String, String)>,
}

pub fn run(repo: &Repo, cfg: &Config) -> Result<Vec<Output>> {
    let Some(rules_path) = cfg.option_str(ID, "rules-path")? else {
        return Ok(Vec::new());
    };
    let dir = cfg
        .option_str(ID, "adr-dir")?
        .unwrap_or_else(|| "docs/adr".to_owned());
    let set = load(repo, &dir);
    let intro = cfg.option_str(ID, "rules-intro")?.unwrap_or_default();
    let outro = cfg.option_str(ID, "rules-outro")?.unwrap_or_default();
    let mut out = vec![Output {
        path: rules_path,
        bytes: render_index(&set, &intro, &outro).into_bytes(),
    }];
    if let Some(path) = cfg.option_str(ID, "baseline-path")? {
        let areas = cfg.option_map(ID, "security-areas")?;
        let intro = cfg.option_str(ID, "baseline-intro")?.unwrap_or_default();
        out.push(Output {
            path,
            bytes: render_baseline(&set, &areas, &intro).into_bytes(),
        });
    }
    Ok(out)
}

fn load(repo: &Repo, dir: &str) -> Vec<Adr> {
    let prefix = format!("{dir}/");
    let mut set = Vec::new();
    for path in &repo.files {
        let Some(name) = path.strip_prefix(&prefix) else {
            continue;
        };
        let Some(m) = ADR_FILE.captures(name) else {
            continue;
        };
        let Some(body) = repo.read(path) else {
            continue;
        };
        let mut adr = Adr {
            num: m[1].to_owned(),
            title: String::new(),
            file: name.to_owned(),
            rules: Vec::new(),
        };
        let mut in_rules = false;
        for line in body.split('\n') {
            if let Some(t) = TITLE.captures(line) {
                t[2].clone_into(&mut adr.title);
            }
            if line.starts_with("## ") {
                in_rules = line == "## Rules";
                continue;
            }
            if in_rules && let Some(text) = line.strip_prefix("- ") {
                adr.rules.push(parse_rule(text));
            }
        }
        set.push(adr);
    }
    set.sort_by(|a, b| a.num.cmp(&b.num));
    set
}

/// Splits a bullet into its statement and its gates. A rule can name more than one gate.
fn parse_rule(text: &str) -> Rule {
    let Some(m) = ANNOTATION.captures(text) else {
        return Rule {
            text: text.to_owned(),
            gates: Vec::new(),
        };
    };
    let mut kind = m[1].to_owned();
    let mut gates = Vec::new();
    for part in format!("{}: {}", &m[1], &m[2]).split(';') {
        let part = part.trim();
        match part.split_once(": ") {
            Some((k, via)) if matches!(k, "CI" | "enforced" | "ref") => {
                k.clone_into(&mut kind);
                gates.push((kind.clone(), via.trim().to_owned()));
            }
            _ => gates.push((kind.clone(), part.to_owned())),
        }
    }
    Rule {
        text: ANNOTATION.replace_all(text, "").trim().to_owned(),
        gates,
    }
}

/// Rewrites the links of a rule for the document it goes into.
fn rebase(text: &str, adr_prefix: &str, up_prefix: &str) -> String {
    let once = ADR_LINK.replace_all(text, |c: &regex::Captures<'_>| {
        format!("]({adr_prefix}{})", &c[1])
    });
    UP_LINK
        .replace_all(&once, |c: &regex::Captures<'_>| {
            format!("]({up_prefix}{})", &c[1])
        })
        .into_owned()
}

fn render_index(set: &[Adr], intro: &str, outro: &str) -> String {
    let total: usize = set.iter().map(|a| a.rules.len()).sum();
    let annotated = set
        .iter()
        .flat_map(|a| &a.rules)
        .filter(|r| !r.gates.is_empty())
        .count();
    let mut b = format!("# Rules Index\n\n{GENERATED}\n\n{intro}");
    let _ = write!(
        b,
        "| Enforcement | Rules |\n| --- | --- |\n| Machine-enforced | {annotated} |\n| Review-enforced | {} |\n| **Total** | **{total}** |\n\n{outro}",
        total - annotated
    );
    for adr in set.iter().filter(|a| !a.rules.is_empty()) {
        let _ = write!(
            b,
            "\n## ADR-{}: {}\n\n[Full decision](../adr/{})\n\n| Rule | Enforced by |\n| --- | --- |\n",
            adr.num, adr.title, adr.file
        );
        for rule in &adr.rules {
            let _ = writeln!(
                b,
                "| {} | {} |",
                cell(&rebase(&rule.text, "../adr/", "../")),
                enforcement(rule)
            );
        }
    }
    b
}

fn render_baseline(set: &[Adr], areas: &[(String, String)], intro: &str) -> String {
    let mut b = format!("# Security Baseline\n\n{GENERATED}\n\n{intro}");
    let mut sorted: Vec<_> = areas.iter().collect();
    sorted.sort();
    for (num, area) in sorted {
        for adr in set.iter().filter(|a| a.num == *num && !a.rules.is_empty()) {
            let _ = write!(
                b,
                "\n## {area}\n\n[ADR-{}: {}](adr/{})\n\n| Control | Enforced by |\n| --- | --- |\n",
                adr.num, adr.title, adr.file
            );
            for rule in &adr.rules {
                let _ = writeln!(
                    b,
                    "| {} | {} |",
                    cell(&rebase(&rule.text, "adr/", "")),
                    enforcement(rule)
                );
            }
        }
    }
    b
}

fn enforcement(rule: &Rule) -> String {
    if rule.gates.is_empty() {
        return "review".to_owned();
    }
    rule.gates
        .iter()
        .map(|(kind, via)| match kind.as_str() {
            "CI" => format!("`{via}` in CI"),
            "enforced" => format!("admission: {via}"),
            _ => format!("standard: {via}"),
        })
        .collect::<Vec<_>>()
        .join(", ")
}

/// A pipe in a rule would end its table column.
fn cell(text: &str) -> String {
    text.trim().replace('|', r"\|")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_rule_keeps_every_gate() {
        let rule = parse_rule("All images are pinned. `(CI: lint-tags; enforced: Kyverno)`");
        assert_eq!(rule.text, "All images are pinned.");
        assert_eq!(enforcement(&rule), "`lint-tags` in CI, admission: Kyverno");
        assert_eq!(enforcement(&parse_rule("No gate.")), "review");
    }

    #[test]
    fn links_are_rebased() {
        assert_eq!(
            rebase("[a](0001-x.md) [b](../guide/y.md)", "../adr/", "../"),
            "[a](../adr/0001-x.md) [b](../guide/y.md)"
        );
        assert_eq!(
            rebase("[a](0001-x.md) [b](../guide/y.md)", "adr/", ""),
            "[a](adr/0001-x.md) [b](guide/y.md)"
        );
    }
}
